class Solution:
    def fixedRatio(self, s, num1, num2):
        from collections import defaultdict
        cnt=defaultdict(int); cnt[0]=1
        D=ans=0
        for c in s:
            ans+=cnt[D]
            D+= num2 if c=='0' else -num1
            cnt[D]+=1
        return ans

