class Solution {
public:
    long long fixedRatio(string s, int num1, int num2){
        unordered_map<long long,long long> cnt{{0,1}};
        long long D=0,ans=0;
        for(char c:s){
            auto it=cnt.find(D); ans+=(it==cnt.end()?0:it->second);
            D+= (c=='0')?num2:-num1;
            cnt[D]++;
        }
        return ans;
    }
};

c.java:
class Solution {
    public long fixedRatio(String s, int num1, int num2){
        Map<Long,Long> cnt=new HashMap<>(); cnt.put(0L,1L);
        long D=0,ans=0;
        for(char c:s.toCharArray()){
            ans+=cnt.getOrDefault(D,0L);
            D+=(c=='0')?num2:-num1;
            cnt.merge(D,1L,Long::sum);
        }
        return ans;
    }
}

