var fixedRatio = function(s, num1, num2) {
    const cnt=new Map([[0,1]]);
    let D=0,ans=0;
    for(const c of s){
        ans+=cnt.get(D)||0;
        D+=(c==='0')?num2:-num1;
        cnt.set(D,(cnt.get(D)||0)+1);
    }
    return ans;
